package main
import("context";"encoding/json";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`SELECT jsonb_build_object('job',j.id,'status',j.status,'fire',j.fire_at,'window_end',j.window_end_at,'attempts',j.attempt_count,'error',j.error_text,'owner',j.lease_owner,'handoff_until',j.handoff_until,'clips',(SELECT count(*) FROM recording_clips c WHERE c.recording_job_id=j.id),'first_clip',(SELECT min(clip_start_at) FROM recording_clips c WHERE c.recording_job_id=j.id),'last_clip',(SELECT max(clip_end_at) FROM recording_clips c WHERE c.recording_job_id=j.id),'pending_uploads',(SELECT count(*) FROM recording_upload_intents u WHERE u.recording_job_id=j.id AND u.status='pending')) FROM recording_jobs j WHERE j.recording_id=408 ORDER BY j.fire_at DESC LIMIT 10`);if e!=nil{panic(e)};defer rows.Close();for rows.Next(){var b []byte;if e=rows.Scan(&b);e!=nil{panic(e)};var x any;_=json.Unmarshal(b,&x);o,_:=json.Marshal(x);fmt.Println(string(o))}}
